import "unicode"

func isPalindrom(s string) bool {
	var bersih []rune
	for _, ch := range s {
		ch = unicode.ToLower(ch)
		if (ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9') {
			bersih = append(bersih, ch)
		}
	}
	for i, j := 0, len(bersih)-1; i < j; i, j = i+1, j-1 {
		if bersih[i] != bersih[j] {
			return false
		}
	}
	return true
}
